javascript:(async()=>{ const ARCH='https://moisesms1999-dev.github.io/archive-/'; const css='position:fixed;inset:0;z-index:2147483647;background:#1a120b;color:#ffd9b0;font:16px/1.4 system-ui,sans-serif;overflow:auto;padding:16px 14px 40px'; const $=(t,p={},...k)=>{const e=document.createElement(t);Object.assign(e,p);if(p.style)e.setAttribute('style',p.style);k.flat().forEach(c=>e.append(c));return e;}; let TOK=(window.___INITIAL_STATE___&&0)||null; try{TOK=(JSON.parse([...document.querySelectorAll('script')].map(s=>s.textContent).find(t=>t&&t.includes('API_TOKEN')).match(/"API_TOKEN":"([^"]+)"/)[0].replace('"API_TOKEN":',''))); }catch(e){} if(!TOK){alert('Abre esto estando en tumblr.com (dashboard o tu blog), con la sesión iniciada.');return;} const box=$('div',{id:'rnc',style:css}); const log=$('div',{style:'font-size:13px;color:#e7b98a;white-space:pre-wrap;max-height:34vh;overflow:auto;margin-top:10px'}); const st=$('div',{style:'color:#9be59b;min-height:1.3em;margin:8px 0'}); const close=$('button',{textContent:'✕ Cerrar',style:'position:absolute;top:10px;right:12px;background:#5a3a1e;color:#ffd9b0;border:0;border-radius:10px;padding:8px 12px;font-weight:700'}); close.onclick=()=>box.remove(); box.append(close,$('h2',{textContent:'🍪 Renacer',style:'color:#ff9a3c;margin:0 0 4px'})); box.append($('p',{textContent:'Publica en el blog que tengas abierto ahora. Tandas de 5, un minuto entre posts.',style:'color:#f3c99a;margin:0 0 12px'})); const api=async(path,opts={})=>{const r=await fetch('https://api.tumblr.com/v2'+path,{credentials:'include',headers:{'Authorization':'Bearer '+TOK,'Content-Type':'application/json','X-Version':'redpop/3/0//redpop/'},...opts});return r.json();}; let blogs=[]; try{const u=await api('/user/info');blogs=u.response.user.blogs.map(b=>b.name);}catch(e){box.append($('p',{textContent:'No pude leer tus blogs: '+e}));} const sel=$('select',{style:'width:100%;padding:11px;border-radius:10px;background:#1a120b;color:#ffd9b0;border:1px solid #5a3a1e;margin-bottom:12px'}); blogs.forEach(n=>sel.append($('option',{value:n,textContent:n}))); box.append(sel); const list=$('div');box.append(list); let items=[]; try{items=await (await fetch(ARCH+'index.json?'+Date.now())).json();}catch(e){box.append($('p',{textContent:'No pude leer el archivo.'}));} let pages={}; for(const it of items){ const b=$('button',{textContent:it.title,style:'display:block;width:100%;text-align:left;background:#3a2412;color:#ffd9b0;border:0;border-radius:10px;padding:12px;margin:0 0 8px;font-weight:700'}); b.onclick=async()=>{st.textContent='Leyendo '+it.title+'…'; const html=await (await fetch(ARCH+it.path+'?'+Date.now())).text(); const m=html.match(/const (?:D|P)=(\[[\s\S]*?\]);\s*const TAGS=("(?:[^"\\]|\\.)*")/); if(!m){st.textContent='Esa página no tiene posts para publicar.';return;} const base=new URL(it.path,ARCH).href.replace(/[^/]*$/,''); let D=JSON.parse(m[1]).map(x=>x.split('MEDIA/').join(base+'media/')); const TAGS=JSON.parse(m[2]); const labs={};let lm;const lre=/data-i="(\d+)"[^>]*>(?:<span[^>]*>[^<]*<\/span>)?<span class="t">([^<]*)<\/span>/g; while((lm=lre.exec(html)))labs[+lm[1]]=lm[2]; showPosts(it.title,D,TAGS,labs); }; list.append(b); } box.append(st,log);document.body.append(box); function showPosts(title,D,TAGS,labs){ list.innerHTML='';box.querySelector('select').style.display=''; const back=$('button',{textContent:'‹ volver',style:'background:#5a3a1e;color:#ffd9b0;border:0;border-radius:10px;padding:8px 12px;margin:0 0 10px;font-weight:700'}); back.onclick=()=>box.remove()||document.body.append(box); list.append($('h3',{textContent:title,style:'color:#ffb066;margin:4px 0 8px'})); const checks=[]; D.forEach((d,i)=>{ const id='rk'+i;const im=(d.match(/<img /g)||[]).length,vi=(d.match(/<figure/g)||[]).length; const row=$('label',{style:'display:flex;gap:8px;align-items:flex-start;margin:0 0 8px;font-size:14px'}); const c=$('input',{type:'checkbox',checked:true});c.dataset.i=i;checks.push(c); row.append(c,$('span',{innerHTML:'<b>'+((labs[i]||('Post '+(i+1))).replace(/</g,'&lt;'))+'</b><br><small style="color:#e7b98a">'+im+' img · '+vi+' vídeos</small>'})); list.append(row); }); const pub=$('button',{textContent:'Publicar los marcados (tanda de 5)',style:'display:block;width:100%;background:#ff9a3c;color:#1a120b;border:0;border-radius:12px;padding:15px;font-weight:800;margin:8px 0'}); pub.onclick=async()=>{ const blog=box.querySelector('select').value; const picks=checks.filter(c=>c.checked).slice(0,5); if(!picks.length){st.textContent='No hay nada marcado.';return;} pub.disabled=true;let ok=0;const chain={}; for(let n=0;n<picks.length;n++){ const i=+picks[n].dataset.i;const body=D[i]; st.textContent='Publicando '+(n+1)+' de '+picks.length+'…'; const ev=(labs[i]||'').match(/^Evidence (\d+)/); let payload={content:[{type:'text',text:body.replace(/<[^>]+>/g,'')}]}; let res; try{ const prev=ev&&chain.evidence&&(+ev[1]===chain.evidence.n+1)?chain.evidence:null; if(prev){ res=await api('/blog/'+blog+'/post/reblog',{method:'POST',body:JSON.stringify({id:prev.id,reblog_key:prev.key,comment:body,tags:TAGS,format:'html'})}); }else{ res=await api('/blog/'+blog+'/post',{method:'POST',body:JSON.stringify({type:'text',format:'html',body:body,tags:TAGS})}); } const id=res&&res.response&&(res.response.id_string||res.response.id); if(id){ok++;log.textContent+='✓ '+(labs[i]||i)+' → '+id+'\n'; if(ev){const g=await api('/blog/'+blog+'/posts?id='+id);const pp=g.response&&g.response.posts&&g.response.posts[0];if(pp)chain.evidence={n:+ev[1],id:id,key:pp.reblog_key};} picks[n].checked=false;picks[n].disabled=true; }else{log.textContent+='✗ '+(labs[i]||i)+' '+JSON.stringify(res&&res.meta||res).slice(0,120)+'\n';} }catch(e){log.textContent+='✗ '+(labs[i]||i)+' '+e+'\n';} log.scrollTop=1e9; if(n<picks.length-1){for(let t=60;t>0;t--){st.textContent='Siguiente en '+t+' s…';await new Promise(r=>setTimeout(r,1000));}} } const left=checks.filter(c=>c.checked).length; st.textContent='Tanda hecha: '+ok+' de '+picks.length+'.'+(left?' Quedan '+left+' marcados: espera y vuelve a pulsar.':' No queda nada.'); pub.disabled=false; }; list.append(pub); } })();